{"content": "// console_top.v — E2 : mire LCD 800×480 + soft USB CDC + SoC AE350 (socle analyseur porté).
//
// Le SoC et sa DDR3 : le socle VALIDÉ de l'analyseur (ae350_soc.v + ddr_subsys + pont Sipeed +
// IP DDR3 standalone Gowin). Le contrôleur DDR3 embarqué du SoC est écarté (faits mesurés :
// son pont AHB interne rend 0x00000000 — ARCHI_V3 § E1, en-tête ae350_soc.v).
// Horloges (faits mesurés V3) : memory_clk 300 MHz (400 ne calibre pas de façon fiable),
// DDR_CLK/HCLK 50 MHz, CORE 800 / AHB = APB 80 / RTC 10 depuis la PLL système.
// La console AE350 (UART2) rejoint le CDC par le pont uart2_to_ep2 (EP2).
`default_nettype none
module console_top (
    input  wire       clk,            // 50 MHz P16
    output wire [5:0] lcd_r,
    output wire [5:0] lcd_g,
    output wire [5:0] lcd_b,
    output wire       lcd_en,
    output wire       lcd_hs,
    output wire       lcd_vs,
    output wire       lcd_bl,
    output wire       lcd_clk,
    output wire [5:0] led,
    // soft USB (brochage usb_ref.cst)
`ifndef CONSOLE_USB_FS_PHY
    inout  wire       usb_dxp_io,
    inout  wire       usb_dxn_io,
    input  wire       usb_rxdp_i,
    input  wire       usb_rxdn_i,
`endif
    output wire       usb_pullup_en_o,
    inout  wire       usb_term_dp_io,
    inout  wire       usb_term_dn_io,
    // DDR3 (brochage pro_ddr_test Sipeed, banques 1.5 V)
    output wire [2:0] ddr_bank,
    output wire       ddr_cs, ddr_ras, ddr_cas, ddr_we, ddr_ck, ddr_ck_n, ddr_cke, ddr_reset_n, ddr_odt,
    output wire [15:0] ddr_addr,
    output wire [3:0]  ddr_dm,
    inout  wire [31:0] ddr_dq,
    inout  wire [3:0]  ddr_dqs, ddr_dqs_n,
    // JTAG du AE350 (PMOD1)
    input  wire       ae350_tck,
    input  wire       ae350_tms,
    input  wire       ae350_tdi,
     output wire       ae350_tdo,
     output wire       ae350_tx_pin,  // espion UART2 sur broche (comme l'analyseur : F19)
    // Carte microSD du dock, en mode SPI (SPI de l'AE350). D1 et D2 inutilisés restent à 1.
    output wire       sd_clk,
    output wire       sd_cmd,
    input  wire       sd_d0,
    output wire       sd_d1,
    output wire       sd_d2,
    output wire       sd_d3,
    input  wire       sd_det
);
    assign sd_d1 = 1'b1;
    assign sd_d2 = 1'b1;
    assign ae350_tx_pin = ae350_tx;
    // ====================== LCD 800×480, 35 MHz ==========================
    wire lcd_clk_pix;
    Gowin_PLL_LCD u_pll_lcd (.clkout0 (lcd_clk_pix), .clkin (clk));
    wire rst_n = 1'b1;
    wire vid_hclk, vid_hrstn, vid_hsel, vid_hwrite, vid_hready;
    wire [31:0] vid_haddr, vid_hwdata, vid_hrdata;
    wire [1:0] vid_htrans;
    wire gpu_clk, gpu_valid, gpu_ready, gpu_data_valid;
    wire [28:0] gpu_addr;
    wire [255:0] gpu_data;
    wire blit_valid, blit_write, blit_ready, blit_rd_valid;
    wire [28:0] blit_addr;
    wire [255:0] blit_wr_data, blit_rd_data;
    wire [31:0] blit_wr_mask;
`ifdef CONSOLE_GPU
    wire bus_hsel,bus_hwrite,bus_hready;
    wire [31:0] bus_haddr,bus_hwdata,bus_hrdata;
    wire [1:0] bus_htrans;
    video_bus_stage u_video_bus (
        .clk(vid_hclk),.resetn(vid_hrstn),
        .s_hsel(vid_hsel),.s_hwrite(vid_hwrite),.s_htrans(vid_htrans),
        .s_haddr(vid_haddr),.s_hwdata(vid_hwdata),.s_hready(vid_hready),.s_hrdata(vid_hrdata),
        .m_hsel(bus_hsel),.m_hwrite(bus_hwrite),.m_htrans(bus_htrans),
        .m_haddr(bus_haddr),.m_hwdata(bus_hwdata),.m_hready(bus_hready),.m_hrdata(bus_hrdata));
    wire [31:0] scan_hrdata, usb_trace_hrdata, usb_msc_hrdata;
    // Conserver la frontière du mux de registres GPU : sans elle, la
    // synthèse le disperse dans celui du pont CPU (r622 : fil de 11,63 ns
    // depuis read_select[13]). Aucun registre ni cycle AHB supplémentaire.
    wire [31:0] blit_hrdata /* synthesis syn_keep=1 */;
    wire scan_hready, blit_hready, usb_trace_hready, usb_msc_hready;
    reg blit_selected, usb_trace_selected;
    always @(posedge vid_hclk) begin
        if (!vid_hrstn) begin blit_selected <= 1'b0; usb_trace_selected <= 1'b0; end
        else if (bus_hsel) begin
            blit_selected <= bus_haddr[12]; usb_trace_selected <= bus_haddr[13];
        end
    end
    // E9002000 : trace USB ; E9003000 : disque USB (usb_msc_port). Les réponses de ces deux
    // esclaves sortent de registres : elles sont réunies d'abord, puis prennent la place qu'avait
    // la trace seule dans le multiplexeur. Les branches critiques (affichage, blitter) gardent
    // ainsi exactement la profondeur logique du R31.
    wire [31:0] usb_leg_hrdata = blit_selected ? usb_msc_hrdata : usb_trace_hrdata;
    wire        usb_leg_hready = blit_selected ? usb_msc_hready : usb_trace_hready;
    assign bus_hrdata = usb_trace_selected ? usb_leg_hrdata : (blit_selected ? blit_hrdata : scan_hrdata);
    assign bus_hready = usb_trace_selected ? usb_leg_hready : (blit_selected ? blit_hready : scan_hready);
    // The stage emits exactly one address pulse after the previous backend
    // transaction and idle gap. No slave-ready feedback enters another HSEL.
    gpu_scanout u_gpu (
        .hclk(vid_hclk), .hresetn(vid_hrstn), .hsel(bus_hsel && !bus_haddr[13] && !bus_haddr[12]), .hwrite(bus_hwrite),
        .haddr(bus_haddr), .hwdata(bus_hwdata), .htrans(bus_htrans), .hrdata(scan_hrdata), .hready(scan_hready),
        .pixel_clk(lcd_clk_pix), .mem_clk(gpu_clk),
        .fetch_valid(gpu_valid), .fetch_addr(gpu_addr), .fetch_ready(gpu_ready),
        .fetch_data(gpu_data), .fetch_data_valid(gpu_data_valid),
        .lcd_en(lcd_en), .lcd_hs(lcd_hs), .lcd_vs(lcd_vs), .lcd_r(lcd_r), .lcd_g(lcd_g), .lcd_b(lcd_b)
    );
    gpu_accel u_accel (
        .hclk(vid_hclk), .hresetn(vid_hrstn), .hsel(bus_hsel && !bus_haddr[13] && bus_haddr[12]), .hwrite(bus_hwrite),
        .haddr(bus_haddr), .hwdata(bus_hwdata), .htrans(bus_htrans), .hrdata(blit_hrdata), .hready(blit_hready),
        .mem_clk(gpu_clk), .valid(blit_valid), .write(blit_write), .addr(blit_addr),
        .wr_data(blit_wr_data), .wr_mask(blit_wr_mask), .ready(blit_ready),
        .rd_data(blit_rd_data), .rd_valid(blit_rd_valid));
    // Read through AE350 JTAG even if the USB control endpoint is unusable.
    // The E9002000 window adds no control to the USB datapath.
`ifndef CONSOLE_NO_USB_TRACE
    usb_idle_trace u_usb_idle_trace (
        .clk(phy_clk),.reset_n(vid_hrstn && !rst_usb),.bus_reset(usb_busreset),.sof(usb_sof),
        .rx_active(PHY_RXACTIVE),.rx_valid(PHY_RXVALID),.rx_error(PHY_RXERROR),.rx_data(PHY_DATAIN),
        .tx_valid(PHY_TXVALID),.tx_ready(PHY_TXREADY),.tx_data(PHY_DATAOUT),.endpoint(endpt_sel),.cork(usb_txcork),
        .hclk(vid_hclk),.hsel(bus_hsel && bus_haddr[13] && !bus_haddr[12]),.hwrite(bus_hwrite),
        .htrans(bus_htrans),.haddr(bus_haddr),.hwdata(bus_hwdata),.hrdata(usb_trace_hrdata),.hready(usb_trace_hready));
`else
    // Essai de fermeture du timing sans l'observateur de diagnostic USB (3 200 registres).
    assign usb_trace_hrdata = 32'd0;
    assign usb_trace_hready = 1'b1;
`endif
    // Disque USB : octets des endpoints bulk EP1 du stockage de masse.
    wire        msc_flush, msc_tx_dval, msc_rx_rdy, msc_rx_dval, msc_bot_reset;
    wire [7:0]  msc_tx_data, msc_rx_data;
    wire [15:0] msc_tx_committed, msc_tx_sent;
    wire msc_halted, msc_halt_request;
    usb_msc_port u_usb_msc_port (
        .clk(phy_clk),.reset_n(vid_hrstn && !rst_usb),.bus_reset(usb_busreset),.bot_reset(msc_bot_reset),
        .online(usb_online),.highspeed(usb_highspeed),.ep_flush(msc_flush),
        .ep_halted(msc_halted),.halt_request(msc_halt_request),
        .ep_tx_dval(msc_tx_dval),.ep_tx_data(msc_tx_data),
        .ep_tx_committed(msc_tx_committed),.ep_tx_sent(msc_tx_sent),
        .ep_rx_rdy(msc_rx_rdy),.ep_rx_dval(msc_rx_dval && !msc_halted),.ep_rx_data(msc_rx_data),
        .hclk(vid_hclk),.hsel(bus_hsel && bus_haddr[13] && bus_haddr[12]),.hwrite(bus_hwrite),
        .htrans(bus_htrans),.haddr(bus_haddr),.hwdata(bus_hwdata),.hrdata(usb_msc_hrdata),.hready(usb_msc_hready));
`else
    lcd_timing u_lcd (
        .lcd_clk(lcd_clk_pix), .rst_n(rst_n), .lcd_en(lcd_en), .lcd_hs(lcd_hs), .lcd_vs(lcd_vs),
        .lcd_r(lcd_r), .lcd_g(lcd_g), .lcd_b(lcd_b));
    assign vid_hrdata = 32'd0;
    assign vid_hready = 1'b1;
    assign gpu_valid = 1'b0;
    assign gpu_addr = 29'd0;
    assign blit_valid = 0; assign blit_write = 0; assign blit_addr = 0;
    assign blit_wr_data = 0; assign blit_wr_mask = 32'hffffffff;
`endif
    assign lcd_bl = rst_n;
    assign lcd_clk = lcd_clk_pix;

    // ====================== soft USB CDC (copie Sipeed E0b) ==============
    wire pll_f_lock, pll_b_lock, clk48, fclk_960m, phy_clk;
    Gowin_PLL_F u_pll_f (.lock (pll_f_lock), .clkout0 (clk48), .clkin (clk), .reset (1'b0));
    // UG306-1.0.9E, table 5-2: monitor LOCK continuously for at least 2 ms.
    // Use the independent board 50 MHz reference while PLL outputs settle:
    // 104000 cycles = 2.08 ms for each stage of the cascaded PLLs.
    // Then synchronize release into the controller's 60 MHz clock domain.
    // Internal PHY calibration starts after PHY_RESET is released;
    // these qualification delays do not include that calibration.
    wire pll_b_reset, phy_lock_reset, rst_usb;
    usb_reset_release #(.HOLD_CYCLES(104000)) u_usb_ref_start
        (.clk(clk), .locked(pll_f_lock), .reset(pll_b_reset));
    Gowin_PLL_B u_pll_b (.lock (pll_b_lock),
`ifdef CONSOLE_USB_FS_PHY
        .clkout0 (),
`else
        .clkout0 (fclk_960m),
`endif
        .clkout1 (phy_clk), .clkin (clk48), .reset (pll_b_reset));
    usb_reset_release #(.HOLD_CYCLES(104000)) u_usb_phy_start (.clk(clk),
        .locked(pll_f_lock & pll_b_lock & ~pll_b_reset), .reset(phy_lock_reset));
    usb_reset_release #(.HOLD_CYCLES(64)) u_usb_controller_start
        (.clk(phy_clk), .locked(~phy_lock_reset), .reset(rst_usb));

    wire        usb_highspeed, usb_online, usb_suspend, usb_busreset, usb_sof;
    // The controller registers usbrst_o with a synchronous SET. It cannot
    // propagate lock loss while phy_clk is stopped. Reset all application
    // state together with the UART bridge, also during that interval.
    wire        usb_app_reset = RESET | usb_busreset;
    wire [1:0]  PHY_XCVRSELECT, PHY_OPMODE, PHY_LINESTATE;
    wire        PHY_TERMSELECT, PHY_TXVALID, PHY_TXREADY, PHY_RXVALID, PHY_RXACTIVE, PHY_RXERROR;
    wire [7:0]  PHY_DATAIN, PHY_DATAOUT;
    wire        PHY_RESET;
    wire [15:0] DESC_DEV_ADDR, DESC_DEV_LEN, DESC_QUAL_ADDR, DESC_QUAL_LEN,
                DESC_FSCFG_ADDR, DESC_FSCFG_LEN, DESC_HSCFG_ADDR, DESC_HSCFG_LEN,
                DESC_OSCFG_ADDR, DESC_BOS_ADDR, DESC_BOS_LEN,
                DESC_STRLANG_ADDR, DESC_STRVENDOR_ADDR, DESC_STRVENDOR_LEN,
                DESC_STRPRODUCT_ADDR, DESC_STRPRODUCT_LEN,
                DESC_STRSERIAL_ADDR, DESC_STRSERIAL_LEN;
    wire [7:0]  DESCROM_RDAT, DESC_INDEX, DESC_TYPE;
    wire [15:0] DESCROM_RADDR;
    wire        DESCROM_HAVE_STRINGS;
    wire        RESET = rst_usb;
    wire        setup_active;
    wire [3:0]  endpt_sel;
    wire        usb_rxval, usb_rxact, usb_rxpktval, usb_rxrdy;
    wire [7:0]  usb_rxdat;
    wire        usb_txact, usb_txpop, usb_txpktfin, usb_txcork;
    wire [7:0]  usb_txdat;
    wire [11:0] usb_txdat_len;
    wire [7:0]  endpt0_dat;
    wire        endpt0_send;
    wire [11:0] uart_config_txdat_len;
    wire        ep_usb_rxrdy, ep_usb_txcork, ep2_rx_dval;
    wire [11:0] ep_usb_txlen; wire [7:0] ep_usb_txdat;
    wire [7:0]  ep2_rx_data;
    wire [7:0]  inf_alter_i, inf_alter_o, inf_sel_o;
    wire        inf_set_o;
    reg  [7:0]  interface0_alter, interface1_alter;
    wire        uart_en;
    wire [31:0] uart_dte_rate;
    wire [7:0]  uart_char_format, uart_parity_type, uart_data_bits;
    wire        uart_rx_data_val;      // EP2 TX : impulsion par octet (console AE350)
    wire [7:0] uart_rx_data;
    wire ep2_rx_rdy;

    localparam ENDPT_UART_CONFIG = 4'd0;

    // LED0 = USB configuré, LED1 = PLL_F, LED2 = ae350_rstn, LED3 = DDR3 lock, LED4 = ddr3_stop, LED5 = UART2
    assign led[0] = ~usb_online;
    assign led[1] = ~pll_f_lock;
    assign led[2] = soc_dbg[0];        // ae350_rstn : 1 = CPU actif
    assign led[3] = soc_dbg[1];        // ddr3_lock
    reg led_uart = 1'b1;               // activité après décodage d'un octet UART2 valide
    always @(posedge phy_clk or posedge RESET)
        if (RESET) led_uart <= 1'b1;
        else if (uart_rx_data_val) led_uart <= ~led_uart;
    assign led[5] = led_uart;

    usb_fifo u_usb_fifo (
`ifdef CONSOLE_USB_DIAG
        .diagnostic_data(fifo_diagnostic),
`endif
        .i_clk         (phy_clk),
        .i_reset       (usb_app_reset),
        .i_usb_endpt   (endpt_sel),
        .i_usb_rxact   (usb_rxact),
        .i_usb_rxval   (usb_rxval),
        .i_usb_rxpktval(usb_rxpktval),
        .i_usb_rxdat   (usb_rxdat),
        .o_usb_rxrdy   (ep_usb_rxrdy),
        .i_usb_txact   (usb_txact),
        .i_usb_txpop   (usb_txpop),
        .i_usb_txpktfin(usb_txpktfin),
        .o_usb_txcork  (ep_usb_txcork),
        .o_usb_txlen   (ep_usb_txlen),
        .o_usb_txdat   (ep_usb_txdat),
`ifdef CONSOLE_GPU
        .i_ep1_tx_clk  (phy_clk),
        .i_ep1_tx_max  (usb_highspeed ? 12'd512 : 12'd64),
        .i_ep1_tx_dval (msc_tx_dval),
        .i_ep1_tx_data (msc_tx_data),
        .i_ep1_flush   (msc_flush),
        .i_ep1_tx_committed(msc_tx_committed),
        .o_ep1_tx_sent (msc_tx_sent),
        .i_ep1_rx_clk  (phy_clk),
        .i_ep1_rx_rdy  (msc_rx_rdy && !msc_halted),
        .o_ep1_rx_dval (msc_rx_dval),
        .o_ep1_rx_data (msc_rx_data),
`else
        .i_ep1_tx_clk  (phy_clk),
        .i_ep1_tx_max  (12'd64),
        .i_ep1_tx_dval (1'b0),
        .i_ep1_tx_data (8'd0),
        .i_ep1_flush   (1'b0),
        .i_ep1_tx_committed(16'd0),
        .o_ep1_tx_sent (),
        .i_ep1_rx_clk  (phy_clk),
        .i_ep1_rx_rdy  (1'b0),
        .o_ep1_rx_dval (),
        .o_ep1_rx_data (),
`endif
        .i_ep2_tx_clk  (phy_clk),
        .i_ep2_tx_max  (12'd64),
        .i_ep2_tx_dval (uart_rx_data_val & usb_online),
        .i_ep2_tx_data (uart_rx_data[7:0]),
        .i_ep2_rx_clk  (phy_clk),
        .i_ep2_rx_rdy  (ep2_rx_rdy),
        .o_ep2_rx_dval (ep2_rx_dval),
        .o_ep2_rx_data (ep2_rx_data)
    );
    // EP0 status OUT must be accepted even for requests handled internally
    // by the controller. Controller 3.2 NAKs that status when RXRDY is low.
    assign usb_rxrdy     = (endpt_sel == ENDPT_UART_CONFIG) ? 1'b1 :
                          (endpt_sel == 1 && msc_halted) ? 1'b0 : ep_usb_rxrdy;
    assign usb_txcork    = (endpt_sel == ENDPT_UART_CONFIG) ? 1'b0 :
                          (endpt_sel == 1 && msc_halted) ? 1'b1 : ep_usb_txcork;
    assign usb_txdat     = (endpt_sel == ENDPT_UART_CONFIG) ? endpt0_dat : ep_usb_txdat;
    assign usb_txdat_len = (endpt_sel == ENDPT_UART_CONFIG) ? uart_config_txdat_len : ep_usb_txlen;

    always @(posedge phy_clk or posedge RESET) begin
        if (RESET) begin
            interface0_alter <= 8'd0; interface1_alter <= 8'd0;
        end else if (inf_set_o) begin
            if (inf_sel_o == 8'd0)      interface0_alter <= inf_alter_o;
            else if (inf_sel_o == 8'd1) interface1_alter <= inf_alter_o;
        end
    end
    assign inf_alter_i = (inf_sel_o == 8'd0) ? interface0_alter :
                         (inf_sel_o == 8'd1) ? interface1_alter : 8'd0;

`ifdef CONSOLE_USB_FULL_SPEED
    localparam USB_HS_SUPPORT = 0;
`else
    localparam USB_HS_SUPPORT = 1;
`endif
`ifdef CONSOLE_GPU
    localparam USB_MSC = 1;   // composite : port série CDC + disque (stockage de masse)
`else
    localparam USB_MSC = 0;
    wire msc_bot_reset;
    wire msc_halted=1'b0;
`endif
    usb_desc #(
        .SERIALSTR("11252024"), .SERIALSTR_LEN(8),
        .VENDORSTR("Electrosens"), .VENDORSTR_LEN(11),
        .PRODUCTSTR("MegaPro Console"), .PRODUCTSTR_LEN(15),
        .VENDORID(16'h359F), .PRODUCTID(16'h2011),
        .VERSIONBCD(USB_MSC ? 16'h0200 : 16'h0112), .HSSUPPORT(USB_HS_SUPPORT), .SELFPOWERED(0),
        .MSC(USB_MSC)
    ) u_usb_desc (
        .CLK(phy_clk), .RESET(RESET), .i_pid(16'd0), .i_vid(16'd0),
        .i_descrom_raddr(DESCROM_RADDR), .o_descrom_rdat(DESCROM_RDAT),
        .o_desc_dev_addr(DESC_DEV_ADDR), .o_desc_dev_len(DESC_DEV_LEN),
        .o_desc_qual_addr(DESC_QUAL_ADDR), .o_desc_qual_len(DESC_QUAL_LEN),
        .o_desc_fscfg_addr(DESC_FSCFG_ADDR), .o_desc_fscfg_len(DESC_FSCFG_LEN),
        .o_desc_hscfg_addr(DESC_HSCFG_ADDR), .o_desc_hscfg_len(DESC_HSCFG_LEN),
        .o_desc_oscfg_addr(DESC_OSCFG_ADDR),
        .o_desc_strlang_addr(DESC_STRLANG_ADDR),
        .o_desc_strvendor_addr(DESC_STRVENDOR_ADDR), .o_desc_strvendor_len(DESC_STRVENDOR_LEN),
        .o_desc_strproduct_addr(DESC_STRPRODUCT_ADDR), .o_desc_strproduct_len(DESC_STRPRODUCT_LEN),
        .o_desc_strserial_addr(DESC_STRSERIAL_ADDR), .o_desc_strserial_len(DESC_STRSERIAL_LEN),
        .o_descrom_have_strings(DESCROM_HAVE_STRINGS)
    );

    wire [7:0] controller_dataout;
`ifdef CONSOLE_GPU
    usb_msc_guard u_usb_msc_guard (
        .clk(phy_clk),.reset(usb_app_reset),.bot_reset(msc_bot_reset),.abort_request(msc_halt_request),
        .highspeed(usb_highspeed),
        .endpoint(endpt_sel),.rxact(usb_rxact),.rxval(usb_rxval),.rxpktval(usb_rxpktval),.setup(setup_active),.rxdata(usb_rxdat),
        .txpktfin(usb_txpktfin),.txlen(ep_usb_txlen),
        .utmi_data(controller_dataout),.utmi_valid(PHY_TXVALID),.utmi_ready(PHY_TXREADY),
        .halted(msc_halted),.idle(),.phy_data(PHY_DATAOUT));
`else
    assign PHY_DATAOUT=controller_dataout;
`endif
    USB_Device_Controller_Top u_usb_device_controller_top (
        .clk_i(phy_clk), .reset_i(RESET),
        .usbrst_o(usb_busreset), .highspeed_o(usb_highspeed),
        .suspend_o(usb_suspend), .online_o(usb_online),
        .txdat_i(usb_txdat), .txval_i(endpt0_send & (endpt_sel == ENDPT_UART_CONFIG)),
        .txdat_len_i(usb_txdat_len), .txcork_i(usb_txcork), .txiso_pid_i(4'b0011),
        .txpop_o(usb_txpop), .txact_o(usb_txact), .txpktfin_o(usb_txpktfin),
        .rxdat_o(usb_rxdat), .rxval_o(usb_rxval), .rxact_o(usb_rxact), .rxrdy_i(usb_rxrdy),
        .rxpktval_o(usb_rxpktval), .setup_o(setup_active), .endpt_o(endpt_sel), .sof_o(usb_sof),
        .inf_alter_i(inf_alter_i), .inf_alter_o(inf_alter_o), .inf_sel_o(inf_sel_o), .inf_set_o(inf_set_o),
        .descrom_rdata_i(DESCROM_RDAT), .descrom_raddr_o(DESCROM_RADDR),
        .desc_index_o(DESC_INDEX), .desc_type_o(DESC_TYPE),
        .desc_dev_addr_i(DESC_DEV_ADDR), .desc_dev_len_i(DESC_DEV_LEN),
        .desc_qual_addr_i(DESC_QUAL_ADDR), .desc_qual_len_i(DESC_QUAL_LEN),
        .desc_fscfg_addr_i(DESC_FSCFG_ADDR), .desc_fscfg_len_i(DESC_FSCFG_LEN),
        .desc_hscfg_addr_i(DESC_HSCFG_ADDR), .desc_hscfg_len_i(DESC_HSCFG_LEN),
        .desc_oscfg_addr_i(DESC_OSCFG_ADDR),
        .desc_hidrpt_addr_i(16'd0), .desc_hidrpt_len_i(16'd0),
        .desc_bos_addr_i(DESC_BOS_ADDR), .desc_bos_len_i(DESC_BOS_LEN),
        .desc_strlang_addr_i(DESC_STRLANG_ADDR),
        .desc_strvendor_addr_i(DESC_STRVENDOR_ADDR), .desc_strvendor_len_i(DESC_STRVENDOR_LEN),
        .desc_strproduct_addr_i(DESC_STRPRODUCT_ADDR), .desc_strproduct_len_i(DESC_STRPRODUCT_LEN),
        .desc_strserial_addr_i(DESC_STRSERIAL_ADDR), .desc_strserial_len_i(DESC_STRSERIAL_LEN),
        .desc_have_strings_i(DESCROM_HAVE_STRINGS),
        .utmi_dataout_o(controller_dataout), .utmi_txvalid_o(PHY_TXVALID), .utmi_txready_i(PHY_TXREADY),
        .utmi_datain_i(PHY_DATAIN), .utmi_rxactive_i(PHY_RXACTIVE), .utmi_rxvalid_i(PHY_RXVALID),
        .utmi_rxerror_i(PHY_RXERROR), .utmi_linestate_i(PHY_LINESTATE),
        .utmi_opmode_o(PHY_OPMODE), .utmi_xcvrselect_o(PHY_XCVRSELECT),
        .utmi_termselect_o(PHY_TERMSELECT), .utmi_reset_o(PHY_RESET)
    );

`ifdef CONSOLE_USB_FS_PHY
    // Dedicated 60 MHz Full Speed PHY, connected exactly as the validated
    // Pro Dock witness. The unused HS pins are absent from this variant.
    USB_SoftPHY_Top u_usb_fs_softphy_top (
        .clk_i(phy_clk), .rst_i(PHY_RESET),
        .utmi_data_out_i(PHY_DATAOUT), .utmi_txvalid_i(PHY_TXVALID),
        .utmi_op_mode_i(PHY_OPMODE), .utmi_xcvrselect_i(PHY_XCVRSELECT),
        .utmi_termselect_i(PHY_TERMSELECT), .utmi_data_in_o(PHY_DATAIN),
        .utmi_txready_o(PHY_TXREADY), .utmi_rxvalid_o(PHY_RXVALID),
        .utmi_rxactive_o(PHY_RXACTIVE), .utmi_rxerror_o(PHY_RXERROR),
        .utmi_linestate_o(PHY_LINESTATE),
        .usb_dp_io(usb_term_dp_io), .usb_dn_io(usb_term_dn_io)
    );
    assign usb_pullup_en_o = 1'b1;
`else
    USB2_0_SoftPHY_Top u_usb_softphy_top (
        // Assert reset even when phy_clk stops. Both reset release and the
        // qualified lock rising edge are local to the PHY's 60 MHz domain.
        .clk_i(phy_clk), .rst_i(PHY_RESET | rst_usb), .fclk_i(fclk_960m), .pll_locked_i(~rst_usb),
        .utmi_data_out_i(PHY_DATAOUT), .utmi_txvalid_i(PHY_TXVALID),
        .utmi_op_mode_i(PHY_OPMODE), .utmi_xcvrselect_i(PHY_XCVRSELECT),
        .utmi_termselect_i(PHY_TERMSELECT), .utmi_data_in_o(PHY_DATAIN),
        .utmi_txready_o(PHY_TXREADY), .utmi_rxvalid_o(PHY_RXVALID),
        .utmi_rxactive_o(PHY_RXACTIVE), .utmi_rxerror_o(PHY_RXERROR),
        .utmi_linestate_o(PHY_LINESTATE),
        .usb_dxp_io(usb_dxp_io), .usb_dxn_io(usb_dxn_io),
        .usb_rxdp_i(usb_rxdp_i), .usb_rxdn_i(usb_rxdn_i),
        .usb_pullup_en_o(usb_pullup_en_o),
        .usb_term_dp_io(usb_term_dp_io), .usb_term_dn_io(usb_term_dn_io)
    );
`endif

    usb_uart_config u_usb_uart_config (
`ifdef CONSOLE_USB_DIAG
        .diagnostic_data(usb_diagnostic_data),
`endif
        .PHY_CLKOUT(phy_clk), .RESET_IN(usb_app_reset),
        .setup_active(setup_active), .endpt_sel(endpt_sel),
        .usb_rxval(usb_rxval), .usb_rxact(usb_rxact), .usb_rxdat(usb_rxdat),
        .usb_txact(usb_txact), .usb_txpop(usb_txpop),
        .usb_txpktfin(usb_txpktfin),
        .usb_txdat_len_o(uart_config_txdat_len),
        .endpt0_dat_o(endpt0_dat), .endpt0_send_o(endpt0_send), .msc_reset_o(msc_bot_reset),
        .uart1_en_o(uart_en), .uart1_BAUD_RATE_o(uart_dte_rate),
        .uart1_PARITY_BIT_o(uart_parity_type), .uart1_STOP_BIT_o(uart_char_format),
        .uart1_DATA_BITS_o(uart_data_bits)
    );
    defparam u_usb_uart_config.ENDPT_UART_CONFIG = ENDPT_UART_CONFIG;
    defparam u_usb_uart_config.MSC = USB_MSC;

`ifdef CONSOLE_USB_DIAG
    // Observe only; the control endpoint remains usable when bulk CDC stalls.
    reg [31:0] diag_uart,diag_out,diag_delivered,diag_rxerror,diag_packets;
    reg [15:0] diag_pop,diag_ack;
    reg [31:0] diag_status;
    // Slow board state, observed through two registers in the USB domain.
    // These bits never control resets or data flow. Keep them live on EP0,
    // including when the CPU cannot answer any bulk command.
    reg [3:0] diag_board_meta,diag_board_sync;
    always @(posedge phy_clk or posedge usb_app_reset)begin
        if(usb_app_reset)begin diag_board_meta<=0;diag_board_sync<=0;end
        else begin
            diag_board_meta<={pll_ae350_lock,soc_dbg[2:0]};
            diag_board_sync<=diag_board_meta;
        end
    end
    reg [7:0] diag_last_uart,diag_last_out,diag_last_delivered;
    wire [31:0] fifo_diagnostic;
    wire [255:0] usb_tx_packet_history;
    usb_packet_trace #(.INPUT_PIPELINE(1)
`ifdef CONSOLE_USB_CAPTURE_FIRST
        ,.CAPTURE_FIRST(1)
`endif
        ) u_usb_packet_trace(.clk(phy_clk),.reset(usb_app_reset),
        .new_packet(endpt_sel==2 && !usb_txpktfin && fifo_diagnostic[24] && !fifo_diagnostic[27]),
        .valid(PHY_TXVALID),.ready(PHY_TXREADY),.data(PHY_DATAOUT),
        .endpoint(endpt_sel),.cork(usb_txcork),.active(usb_txact),
        .length(usb_txdat_len),.history(usb_tx_packet_history),
        .rx_active(PHY_RXACTIVE),.rx_valid(PHY_RXVALID),.rx_error(PHY_RXERROR),
        .rx_data(PHY_DATAIN),.packet_ack(usb_txpktfin),.fifo_pending(fifo_diagnostic[27]));
    wire [511:0] usb_diagnostic_data={usb_tx_packet_history,diag_packets,diag_rxerror,
        8'hd1,diag_last_delivered,diag_last_out,diag_last_uart,
        diag_board_sync,diag_status[27:0],diag_ack,diag_pop,diag_delivered,diag_out,diag_uart};
    always @(posedge phy_clk or posedge usb_app_reset)begin
        if(usb_app_reset)begin
            diag_uart<=0;diag_out<=0;diag_delivered<=0;diag_rxerror<=0;diag_packets<=0;
            diag_pop<=0;diag_ack<=0;diag_status<=0;
            diag_last_uart<=0;diag_last_out<=0;diag_last_delivered<=0;
        end else begin
            if(uart_rx_data_val)begin diag_uart<=diag_uart+1'b1;diag_last_uart<=uart_rx_data;end
            if(ep2_rx_dval)begin diag_delivered<=diag_delivered+1'b1;diag_last_delivered<=ep2_rx_data;end
            if(PHY_RXERROR)diag_rxerror<=diag_rxerror+1'b1;
            if(endpt_sel==2)begin
                diag_status<=fifo_diagnostic;
                if(usb_rxval)begin diag_out<=diag_out+1'b1;diag_last_out<=usb_rxdat;end
                if(usb_rxpktval)diag_packets<=diag_packets+1'b1;
                if(usb_txpop)diag_pop<=diag_pop+1'b1;
                if(usb_txpktfin)diag_ack<=diag_ack+1'b1;
            end
        end
    end
`endif

    // ====================== AE350 : PLLs + SoC + DDR3 (socle analyseur) ======================
    wire        core_clk, ahb_clk, apb_clk, rtc_clk, bus80_clk, pll_ae350_lock;  // horloges du SoC (PLL AE350)
    wire        ddr_init;               // 1 : calibration DDR3 terminée (sortie du socle)
    wire        ae350_tx, ae350_rx;     // console UART2 du AE350
    wire ddr3_pll_lock, ddr3_memory_clk, ddr3_clk_in, ddr3_stop, ddr3_init_completed;
    wire        ae350_rstn, ddr3_rstn;
    wire [3:0] soc_dbg;
    wire [7:0]  soc_ahb_dbg;
    wire [15:0] soc_ddr_dbg;
    wire [63:0] ev_data_unused; wire ev_ready_unused, evin_valid_unused;
    wire [31:0] evin_data_unused;
    wire [63:0] rr_data_unused; wire rr_valid_unused;
    // PLL système du AE350 (socle analyseur : lock + init_clk + PLL_INIT) :
    // clkout0 = 80 MHz (bus AHB/APB), clkout1 = core 800 MHz, clkout4 = RTC 10 MHz
    Gowin_PLL_AE350 u_pll_ae350 (
        .lock    (pll_ae350_lock),
        .clkin   (clk),
        .init_clk (clk),
        .clkout0 (bus80_clk), .clkout1 (core_clk), .clkout2 (), .clkout3 (), .clkout4 (rtc_clk),
        .enclk0  (1'b1), .enclk1 (1'b1), .enclk2 (1'b1), .enclk3 (1'b1), .enclk4 (1'b1)
    );
    // ahb_clk/apb_clk : DÉJÀ déclarés ligne 232 (wire) : NE PAS redéclarer ici !
    // (EX2830 : « Second declaration of 'ahb_clk' is ignored » : le wire local était ignoré,
    //  l'entrée AHB_CLK du SoC restait non câblée → bus APB mort → CPU figé au 1er accès APB.)
    assign ahb_clk = bus80_clk;
    assign apb_clk = ahb_clk;   // APB = net de l'AHB (1:1 exigé par le SoC, en-tête du socle)
    // Reset du CPU : attend le LOCK de la PLL AE350 (schéma de l'analyseur : rst = sync ~lock)
    reg [1:0] ae350_rst_sync = 2'b11;
    always @(posedge bus80_clk) ae350_rst_sync <= {ae350_rst_sync[0], ~pll_ae350_lock};
    wire ae350_por_n = ~ae350_rst_sync[1];

    // SoC AE350 + DDR3 standalone + pont Sipeed (socle analyseur, validé V3)
    wire core_wfi_w;                 // CORE0_WFI_MODE du cœur (preuve de vie sans bus)
    ae350_soc u_soc (
        .clk50(clk),
        .rst_key_n(ae350_por_n),
        .core_clk(core_clk), .ahb_clk(ahb_clk), .apb_clk(apb_clk), .rtc_clk(rtc_clk),
        .ddr_bank(ddr_bank), .ddr_cs(ddr_cs), .ddr_ras(ddr_ras), .ddr_cas(ddr_cas), .ddr_we(ddr_we),
        .ddr_ck(ddr_ck), .ddr_ck_n(ddr_ck_n), .ddr_cke(ddr_cke), .ddr_reset_n(ddr_reset_n), .ddr_odt(ddr_odt),
        .ddr_addr(ddr_addr), .ddr_dm(ddr_dm), .ddr_dq(ddr_dq), .ddr_dqs(ddr_dqs), .ddr_dqs_n(ddr_dqs_n),
        .tck(ae350_tck), .tms(ae350_tms), .tdi(ae350_tdi), .tdo(ae350_tdo),
        .uart2_tx(ae350_tx), .uart2_rx(ae350_rx), .ddr_init(ddr_init), .dbg(soc_dbg),
        .sd_clk(sd_clk), .sd_cmd(sd_cmd), .sd_miso(sd_d0), .sd_cs_n(sd_d3), .sd_detect(sd_det),
        .ahb_dbg(soc_ahb_dbg), .ddr_dbg(soc_ddr_dbg), .core_wfi_dbg(core_wfi_w),
        // Legacy acquisition inputs are inactive; video uses its own DDR port.
        .ev_clk(clk), .ev_valid(1'b0), .ev_data(64'd0),
        .evin_valid(), .evin_data(), .evin_ready(1'b0),
        .rr_valid(), .rr_data(), .rr_ready(1'b0),
        .acq_v3(1'b0), .acq_start(1'b0), .acq_run(1'b0), .acq_div(8'd0), .acq_mask(16'hFFFF),
        .acq_now(32'd0),
        .vid_hclk(vid_hclk), .vid_hrstn(vid_hrstn), .vid_hsel(vid_hsel), .vid_hwrite(vid_hwrite),
        .vid_haddr(vid_haddr), .vid_hwdata(vid_hwdata), .vid_htrans(vid_htrans),
        .vid_hrdata(vid_hrdata), .vid_hready(vid_hready),
        .gpu_clk(gpu_clk), .gpu_valid(gpu_valid), .gpu_addr(gpu_addr), .gpu_ready(gpu_ready),
        .gpu_data(gpu_data), .gpu_data_valid(gpu_data_valid),
        .blit_valid(blit_valid), .blit_write(blit_write), .blit_addr(blit_addr),
        .blit_wr_data(blit_wr_data), .blit_wr_mask(blit_wr_mask), .blit_ready(blit_ready),
        .blit_rd_data(blit_rd_data), .blit_rd_valid(blit_rd_valid)
    );
    // LED4 = WFI du cœur : si le CPU exécute la boucle wfi, le signal monte → LED s'allume
    assign led[4] = ~core_wfi_w;

    // ====================== pont UART2 (AE350) ↔ CDC EP2 ===================
    uart2_to_ep2 u_pont (
        .phy_clk          (phy_clk),
        .reset            (usb_app_reset),
        .uart2_txd        (ae350_tx),
        .uart2_rxd        (ae350_rx),
        .uart_rx_data_val (uart_rx_data_val),
        .uart_rx_data     (uart_rx_data),
        .ep2_rx_dval      (ep2_rx_dval),
        .ep2_rx_data      (ep2_rx_data),
        .ep2_rx_rdy       (ep2_rx_rdy)
    );

endmodule
`default_nettype wire
"}

{"content": "// usb_msc_port.v — accès du firmware aux deux endpoints bulk du disque USB
// (interface stockage de masse, EP1 OUT et EP1 IN). Le protocole Bulk-Only
// et SCSI est entièrement dans le firmware ; ce module ne transporte que des
// octets et garantit les frontières de paquets en émission.
//
// Fenêtre AHB (0xE9003000) :
//   +00 R  identité 0x554d5343 (« UMSC »)
//   +04 R  état : bit0 octet reçu disponible, bit1 émission vide (tout octet
//          validé a été acquitté par l'hôte), bit2 reset du bus vu,
//          bit3 reset Bulk-Only vu, bit4 purge en cours, bit5 configuré,
//          bit6 High Speed, bit7 perte (émission ou réception saturée),
//          bit8 le firmware sert le disque, bit9 service demandé,
//          bit10 garde BOT verrouillé (jusqu'au reset hôte),
//          bits 31:16 octets émis non encore acquittés
//   +08 R  octet reçu : bit31 = 1 si aucun octet, sinon bits 7:0 et retrait
//   +0c W  octet à émettre (bits 7:0)
//   +10 W  validation : tous les octets écrits deviennent visibles de l'hôte
//   +14 W  commande : bit0 purge des deux sens, bit1 demande à servir le
//          disque, bit2 efface « reset du bus », bit3 efface « reset
//          Bulk-Only », bit5 rend le disque, bit6 verrouille BOT, bit7 efface « perte »
//   +18 R  octets écrits (15:0) et acquittés (31:16), compteurs modulo 65536
//   +1c W  quatre octets à émettre, celui des bits 7:0 en premier
//   +20 R  quatre octets reçus, le premier dans les bits 7:0, et retrait.
//          À ne lire que si +24 en annonce au moins quatre ; sinon la lecture
//          rend ce qu'elle a après 15 cycles et lève « perte »
//   +24 R  nombre d'octets reçus disponibles (valeur prudente)
//   +28 R  version du contrat BOT : 1 = frontières de paquets + STALL
//
// Émission : les octets et le marqueur de validation traversent la même FIFO
// double horloge, donc dans l'ordre. Côté USB, usb_fifo n'annonce à l'hôte
// que min(validés − acquittés, taille de paquet) : un bloc en cours
// d'écriture n'est jamais pris pour un paquet court. Écrire tant que le
// niveau non acquitté (bits 31:16 de l'état) ne dépasse pas 3 576 ; au-delà l'octet est
// refusé et « perte » est levé.
// Aucune attente AHB ne dépend de l'horloge USB.
//
// Lecteur sans carte : tant qu'aucun firmware ne sert le disque, ce module
// répond lui-même à l'hôte comme un lecteur de cartes vide (INQUIRY et
// REQUEST SENSE réussis, « support absent » pour le reste, phases de données
// respectées). Sans cela, un firmware qui ignore le disque laisserait l'hôte
// sans réponse : il réinitialiserait le périphérique entier, port série
// compris. Le firmware demande le disque (bit1 de la commande) et l'obtient
// entre deux commandes de l'hôte (bit8 de l'état). Il le garde tant qu'il
// accède à cette fenêtre : après 2^WATCHDOG_BITS cycles AHB sans accès
// (processeur arrêté, autre programme chargé), le lecteur redevient vide.
`default_nettype none
module usb_msc_port #(
    parameter WATCHDOG_BITS = 29        // 6,7 s à 80 MHz
) (
    input  wire        clk,            // 60 MHz, domaine du contrôleur USB
    input  wire        reset_n,        // asynchrone, commun aux deux domaines
    input  wire        bus_reset,      // clk : reset du bus USB
    input  wire        bot_reset,      // clk : impulsion, requête Bulk-Only Reset
    input  wire        online,         // clk
    input  wire        highspeed,      // clk
    input  wire        ep_halted,      // clk : erreur du garde BOT
    output wire        halt_request,   // clk : demande firmware synchronisée
    output wire        ep_flush,       // clk : remet à zéro les tampons EP1 de usb_fifo
    output reg         ep_tx_dval,
    output reg  [7:0]  ep_tx_data,
    output reg  [15:0] ep_tx_committed,
    input  wire [15:0] ep_tx_sent,
    output wire        ep_rx_rdy,
    input  wire        ep_rx_dval,
    input  wire [7:0]  ep_rx_data,
    input  wire        hclk, hsel, hwrite,
    input  wire [1:0]  htrans,
    input  wire [31:0] haddr, hwdata,
    output reg  [31:0] hrdata,
    output wire        hready
);
    // Sortie de reset propre à chaque horloge, puis vue croisée (comme usb_idle_trace).
    // syn_preserve : sinon la synthèse fusionne ces bascules avec celles, identiques, de usb_idle_trace.
    (* ASYNC_REG="TRUE" *) reg [2:0] hr /* synthesis syn_preserve=1 */ = 0, ur /* synthesis syn_preserve=1 */ = 0;
    (* ASYNC_REG="TRUE" *) reg [1:0] hu /* synthesis syn_preserve=1 */ = 0, uh /* synthesis syn_preserve=1 */ = 0;
    always @(posedge hclk or negedge reset_n)
        if (!reset_n) begin hr <= 0; uh <= 0; end
        else begin hr <= {hr[1:0], 1'b1}; uh <= {uh[0], ur[2]}; end
    always @(posedge clk or negedge reset_n)
        if (!reset_n) begin ur <= 0; hu <= 0; end
        else begin ur <= {ur[1:0], 1'b1}; hu <= {hu[0], hr[2]}; end

    // Purge avec acquittement aller-retour : une horloge USB arrêtée ne
    // peut plus manquer la demande entière. Après observation côté USB,
    // tenir le reset 128 cycles AHB ; attendre ensuite son retrait observé
    // avant les 127 cycles de garde. L'AHB reste toujours consultable.
    reg  [7:0] flush_count;
    wire       flush_h = flush_count[7];
    // Même valeur que (flush_count != 0), sans décodeur combinatoire devant
    // le reset des FIFO et le multiplexeur du rassembleur RX4.
    reg        quiet_h /* synthesis syn_preserve=1 */;
    (* ASYNC_REG="TRUE" *) reg [1:0] flush_s = 0, busrst_s = 0, online_s = 0, hs_s = 0;
    reg        flush_u;
    (* ASYNC_REG="TRUE" *) reg [1:0] flush_ack_h = 0;
    always @(posedge hclk or negedge reset_n)
        if(!reset_n) flush_ack_h<=0;
        else flush_ack_h<={flush_ack_h[0],flush_u};
    always @(posedge clk) begin
        flush_s <= {flush_s[0], flush_h};
        flush_u <= flush_s[1];
    end
    always @(posedge hclk) begin
        busrst_s <= {busrst_s[0], bus_reset};
        online_s <= {online_s[0], online};
        hs_s     <= {hs_s[0], highspeed};
    end
    // Propriété du disque. want_h : le firmware le demande et reste actif.
    // owner_u : accordé côté USB, uniquement entre deux commandes de l'hôte.
    // abandoned : le firmware a cessé de répondre (chien de garde) ; il a pu
    // laisser une commande en plan, les tampons sont alors purgés. Quand il
    // rend le disque lui-même (entre deux commandes), rien n'est purgé : une
    // commande de l'hôte arrivant à cet instant n'est pas perdue.
    reg                     serve, abandoned;
    reg  [2:0]              abandon_delay;
    reg [WATCHDOG_BITS:0]   watchdog;            // le bit de poids fort passe à 1 à l'expiration
    wire                    want_h = serve;      // registre : source propre pour le synchroniseur
    (* ASYNC_REG="TRUE" *) reg [1:0] want_s = 0, owner_s = 0, abandoned_s = 0;
    reg        owner_u;
    reg  [5:0] handback;                 // purge côté USB quand le firmware rend ou perd le disque
    reg        handback_active /* synthesis syn_preserve=1 */;
    wire       empty_idle;               // le lecteur vide est entre deux commandes, émission terminée
    wire       owner_h = owner_s[1];
    always @(posedge clk) begin want_s <= {want_s[0], want_h}; abandoned_s <= {abandoned_s[0], abandoned}; end
    always @(posedge hclk) owner_s <= {owner_s[0], owner_u};
    wire ubase  = !ur[2] || !hu[1] || bus_reset;
    wire uflush = flush_u || handback_active;
    assign ep_flush = uflush;
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin owner_u <= 1'b0; handback <= 6'd0; handback_active<=0; end
        else begin
            // Same cycles as (handback != 0), without a counter reduction
            // in front of the distributed endpoint/FIFO reset and enables.
            if (handback != 0) begin handback <= handback - 1'b1; handback_active<=handback!=1; end
            // Un reset du bus ne retire pas le disque au firmware : il le voit et purge.
            if (!ur[2] || !hu[1]) owner_u <= 1'b0;
            else if (!owner_u) begin
                if (want_s[1] && empty_idle && !handback_active) owner_u <= 1'b1;
                else if (bot_reset) begin handback <= 6'd63; handback_active<=1; end
            end else if (!want_s[1]) begin owner_u <= 1'b0; if (abandoned_s[1]) begin handback <= 6'd63; handback_active<=1; end end
        end
    end
    // Les FIFO vers le firmware restent en reset tant qu'il n'a pas le disque.
    wire hreset = !hr[2] || !uh[1] || busrst_s[1] || quiet_h || !owner_h;
    wire ureset = ubase || uflush || !owner_u;

    // ---- interface AHB ----------------------------------------------------
    reg        write_pending, read_pending;
    reg  [7:0] address;
    reg        seen_bus_reset, seen_bot_reset, lost;
    reg        halt_toggle;
    (* ASYNC_REG="TRUE" *) reg [2:0] halt_s = 0;
    (* ASYNC_REG="TRUE" *) reg [1:0] halted_h = 0;
    always @(posedge clk or negedge reset_n)
        if(!reset_n)halt_s<=0;
        else halt_s<={halt_s[1:0],halt_toggle};
    always @(posedge hclk or negedge reset_n)
        if(!reset_n)halted_h<=0;
        else halted_h<={halted_h[0],ep_halted};
    assign halt_request=halt_s[2]!=halt_s[1];
    reg [15:0] pushed;
    wire       tx_wr_ready;
    wire       rx_valid;
    wire [7:0] rx_byte;
    wire [9:0] rx_rd_count;
    wire [15:0] sent_h;
    wire [15:0] level_h = pushed - sent_h;
    wire       tx_byte   = write_pending && address == 8'h0c;
    wire       tx_quad   = write_pending && address == 8'h1c;
    wire       tx_write  = tx_byte || tx_quad;
    // Place calculée un cycle plus tôt : deux écritures AHB consécutives peuvent
    // la dépasser d'un mot, d'où le seuil à 3 576 pour une limite réelle de 3 584.
    reg        tx_room;
    wire       tx_commit = write_pending && address == 8'h10;
    wire       tx_push   = (tx_write && tx_room || tx_commit) && tx_wr_ready && !hreset;
    // Réception : les octets de la FIFO sont rassemblés par quatre. Une lecture
    // de mot attend au plus 15 cycles AHB que le mot soit complet ; les octets
    // annoncés par +24 sont déjà dans ce domaine, l'attente ne dépend donc pas
    // de l'horloge USB.
    reg [31:0] gather;
    reg  [2:0] gathered;
    reg  [3:0] quad_timer;
    wire       rx_one     = read_pending && address == 8'h08 && gathered != 0 && !hreset;   // jamais pendant quad_wait
    // quad_wait prolonge l'attente d'une lecture de mot dans un registre à part :
    // read_pending garde ainsi la même logique que dans les autres esclaves.
    reg        quad_wait;
    wire       quad_read  = (read_pending || quad_wait) && address == 8'h20;
    wire       quad_stall = quad_read && gathered != 3'd4 && quad_timer != 4'd15 && !hreset;
    wire       quad_done  = quad_read && !quad_stall;
    wire       rx_pop     = rx_valid && !hreset && gathered != 3'd4 && !quad_done;
    // Octets déjà rassemblés + octets en mémoire de la FIFO. L'octet de tête
    // n'est pas ajouté : le compte de la FIFO, en retard d'un cycle, le contient
    // encore quand il vient d'en sortir. La valeur ne dépasse jamais le réel.
    wire [10:0] rx_available = {8'd0, gathered} + {1'b0, rx_rd_count};
    assign hready = !read_pending && !quad_wait;

    // Reset Bulk-Only et pertes : évènements du domaine USB, passés par bascule.
    reg  bot_toggle = 1'b0, lost_toggle = 1'b0;
    (* ASYNC_REG="TRUE" *) reg [2:0] bot_s = 0, lost_s = 0;
    always @(posedge hclk) begin
        bot_s  <= {bot_s[1:0], bot_toggle};
        lost_s <= {lost_s[1:0], lost_toggle};
    end

    always @(posedge hclk or negedge reset_n) begin
        if (!reset_n) begin
            write_pending <= 1'b0; read_pending <= 1'b0; address <= 8'd0; hrdata <= 32'd0;
            flush_count <= 8'd0; quiet_h <= 1'b0; seen_bus_reset <= 1'b0; seen_bot_reset <= 1'b0; lost <= 1'b0;
            pushed <= 16'd0; serve <= 1'b0; watchdog <= {1'b1, {WATCHDOG_BITS{1'b1}}}; tx_room <= 1'b0;
            abandoned <= 1'b0; abandon_delay <= 3'd0;
            gather <= 32'd0; gathered <= 3'd0; quad_timer <= 4'd0; quad_wait <= 1'b0;
            halt_toggle <= 1'b0;
        end else begin
            // Tout accès à la fenêtre prouve que le firmware est vivant. À
            // l'expiration, « abandonné » précède de quatre cycles le retrait
            // de la demande : le domaine USB les voit dans cet ordre.
            // (Accès vu par ses registres : rien ici ne dépend du chemin HREADY.)
            tx_room <= level_h <= 16'd3576;
            if (write_pending || read_pending) watchdog <= {1'b0, {WATCHDOG_BITS{1'b1}}};
            else if (!watchdog[WATCHDOG_BITS]) watchdog <= watchdog - 1'b1;
            else if (serve) begin
                abandoned <= 1'b1; abandon_delay <= abandon_delay + 1'b1;
                if (abandon_delay == 3'd4) serve <= 1'b0;
            end
            write_pending <= hsel && htrans[1] && hwrite && hready;
            read_pending  <= hsel && htrans[1] && !hwrite && hready;
            quad_wait     <= quad_stall;
            quad_timer <= quad_stall ? quad_timer + 1'b1 : 4'd0;
            if (hreset || quad_done) gathered <= 3'd0;
            else if (rx_one) begin
                gather <= {8'd0, gather[31:8]};
                if (rx_pop) gather[8 * (gathered - 3'd1) +: 8] <= rx_byte;
                else gathered <= gathered - 1'b1;
            end else if (rx_pop) begin
                gather[8 * gathered[1:0] +: 8] <= rx_byte;
                gathered <= gathered + 1'b1;
            end
            if (quad_done && gathered != 3'd4) lost <= 1'b1;
            if (hready) address <= haddr[7:0];
            if (flush_count != 0 && (!flush_h || flush_ack_h[1]) &&
                (flush_count != 8'h7f || !flush_ack_h[1]))
                flush_count <= flush_count - 1'b1;
            if (flush_count == 8'd1) quiet_h <= 1'b0;
            // Hors service, le compteur suit les octets émis par le lecteur vide :
            // le niveau d'émission vaut zéro quand le firmware obtient le disque.
            if (busrst_s[1] || quiet_h) pushed <= 16'd0;
            else if (!owner_h) pushed <= sent_h;
            else if (tx_write && tx_push) pushed <= pushed + (tx_quad ? 16'd4 : 16'd1);
            if ((tx_write || tx_commit) && !tx_push) lost <= 1'b1;
            if (lost_s[2] != lost_s[1]) lost <= 1'b1;
            if (bot_s[2] != bot_s[1]) seen_bot_reset <= 1'b1;
            if (busrst_s[1]) seen_bus_reset <= 1'b1;
            if (write_pending && address == 8'h14) begin
                if (hwdata[0]) begin flush_count <= 8'hff; quiet_h <= 1'b1; end
                if (hwdata[1]) begin serve <= 1'b1; abandoned <= 1'b0; abandon_delay <= 3'd0; end
                if (hwdata[5]) serve <= 1'b0;
                if (hwdata[6]) halt_toggle <= !halt_toggle;
                if (hwdata[2] && !busrst_s[1]) seen_bus_reset <= 1'b0;
                if (hwdata[3]) seen_bot_reset <= 1'b0;
                if (hwdata[7]) lost <= 1'b0;
            end
            if ((read_pending || quad_wait) && !quad_stall) begin
                case (address)
                    8'h00: hrdata <= 32'h554d5343;
                    8'h04: hrdata <= {level_h, 5'd0, halted_h[1], serve, owner_h, lost, hs_s[1], online_s[1], quiet_h,
                                      seen_bot_reset, seen_bus_reset, level_h == 0, gathered != 0 && !hreset};
                    8'h08: hrdata <= (gathered != 0 && !hreset) ? {24'd0, gather[7:0]} : 32'h80000000;
                    8'h18: hrdata <= {sent_h, pushed};
                    8'h20: hrdata <= gather;
                    8'h24: hrdata <= hreset ? 32'd0 : {21'd0, rx_available};
                    8'h28: hrdata <= 32'd1;
                    default: hrdata <= 32'd0;
                endcase
            end
        end
    end

    // ---- émission : AHB -> USB ---------------------------------------------
    // Un élément : marqueur de validation, nombre d'octets − 1, jusqu'à quatre
    // octets. Côté USB, un octet part tous les deux cycles (30 Mo/s, au-delà du
    // débit utile d'un endpoint bulk High Speed).
    wire        tx_valid;
    wire [34:0] tx_word;
    reg  [23:0] serial;
    reg  [1:0]  serial_left;
    reg         serial_gap;
    wire        serial_busy = serial_left != 0 || serial_gap;
    wire        serial_emit = serial_left != 0 && !serial_gap;
    ddr_dcfifo #(.WIDTH(35), .DEPTH_LOG2(10)) u_tx (
        .wr_clk(hclk), .wr_rst(hreset), .wr_valid(tx_push),
        .wr_data({tx_commit, tx_quad ? 2'd3 : 2'd0, hwdata}),
        .wr_ready(tx_wr_ready), .wr_full(), .wr_lost(), .wr_count(),
        .rd_clk(clk), .rd_rst(ureset), .rd_valid(tx_valid), .rd_data(tx_word),
        .rd_ready(!ureset && !serial_busy), .rd_count());
    reg [15:0] pushed_u;
    wire tx_take = tx_valid && !ureset && !serial_busy;
    wire tx_first = tx_take && !tx_word[34];
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin serial <= 24'd0; serial_left <= 2'd0; serial_gap <= 1'b0; end
        else if (ureset) begin serial_left <= 2'd0; serial_gap <= 1'b0; end
        else begin
            serial_gap <= 1'b0;
            if (tx_first) begin serial <= tx_word[31:8]; serial_left <= tx_word[33:32]; serial_gap <= 1'b1; end
            else if (serial_emit) begin serial <= {8'd0, serial[23:8]}; serial_left <= serial_left - 1'b1; serial_gap <= 1'b1; end
        end
    end
    wire        empty_tx_dval, empty_tx_commit, empty_rx_rdy;
    wire [7:0]  empty_tx_data;
    wire        empty_reset = ubase || uflush || owner_u;
    wire        tx_idle_u = pushed_u == ep_tx_sent && ep_tx_committed == pushed_u;
    wire        tx_room_u = (pushed_u - ep_tx_sent) < 16'd3584;
    reg [15:0] committed_u;
    // Un étage commun pour octet, validité et compteur publié : aucun
    // marqueur ne dépasse ses données. Il coupe le chemin reset du
    // contrôleur -> sélection/sérialisation -> écriture BSRAM de EP1.
    // Le reset EP1 annule aussi l'octet déjà dans cet étage. tx_idle_u tient
    // compte du compteur publié, donc de cette latence supplémentaire.
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin ep_tx_dval <= 1'b0; ep_tx_data <= 8'd0; ep_tx_committed <= 16'd0; end
        else if (ubase || uflush) begin ep_tx_dval <= 1'b0; ep_tx_data <= 8'd0; ep_tx_committed <= 16'd0; end
        else begin
            ep_tx_dval <= owner_u ? tx_first || serial_emit : empty_tx_dval;
            ep_tx_data <= owner_u ? (serial_emit ? serial[7:0] : tx_word[7:0]) : empty_tx_data;
            ep_tx_committed <= committed_u;
        end
    end
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin pushed_u <= 16'd0; committed_u <= 16'd0; end
        else if (ubase || uflush) begin pushed_u <= 16'd0; committed_u <= 16'd0; end
        else if (!owner_u) begin
            if (empty_tx_dval) pushed_u <= pushed_u + 1'b1;
            if (empty_tx_commit) committed_u <= pushed_u + {15'd0, empty_tx_dval};
        end else begin
            if (tx_first || serial_emit) pushed_u <= pushed_u + 1'b1;
            if (tx_take && tx_word[34]) committed_u <= pushed_u;
        end
    end
    usb_msc_empty u_empty (
        .clk(clk), .reset(empty_reset),
        .rx_rdy(empty_rx_rdy), .rx_dval(ep_rx_dval && !owner_u), .rx_data(ep_rx_data),
        .tx_room(tx_room_u), .tx_idle(tx_idle_u),
        .tx_dval(empty_tx_dval), .tx_data(empty_tx_data), .tx_commit(empty_tx_commit),
        .idle(empty_idle));
    cdc_word #(.WIDTH(16)) u_sent (.src_clk(clk), .src_data(ep_tx_sent), .dst_clk(hclk), .dst_data(sent_h));

    // ---- réception : USB -> AHB --------------------------------------------
    // usb_rx_buf peut encore livrer deux octets après la retombée de rdy :
    // on la retire avec douze places libres.
    wire       rx_wr_ready;
    wire [9:0] rx_wr_count;
    assign ep_rx_rdy = owner_u ? !ureset && rx_wr_count <= 10'd500 : empty_rx_rdy;
    ddr_dcfifo #(.WIDTH(8), .DEPTH_LOG2(9)) u_rx (
        .wr_clk(clk), .wr_rst(ureset), .wr_valid(ep_rx_dval && owner_u), .wr_data(ep_rx_data),
        .wr_ready(rx_wr_ready), .wr_full(), .wr_lost(), .wr_count(rx_wr_count),
        .rd_clk(hclk), .rd_rst(hreset), .rd_valid(rx_valid), .rd_data(rx_byte),
        .rd_ready(rx_pop), .rd_count(rx_rd_count));
    always @(posedge clk) begin
        if (bot_reset) bot_toggle <= !bot_toggle;
        if (ep_rx_dval && owner_u && !rx_wr_ready) lost_toggle <= !lost_toggle;
    end
endmodule
`default_nettype wire
"}

{"content": "// Qualify a PLL lock in the clock domain being released. Assertion is
// asynchronous (also works with a stopped clock); release is registered and
// follows two synchronizer clocks plus HOLD_CYCLES stable clocks.
module usb_reset_release #(
    parameter HOLD_CYCLES = 1024
)(
    input wire clk,
    input wire locked,
    output reg reset = 1'b1
);
    localparam CW = HOLD_CYCLES <= 1 ? 1 : $clog2(HOLD_CYCLES);
    (* syn_preserve = 1 *) reg [1:0] lock_sync = 0;
    reg [CW-1:0] count = 0;
    always @(posedge clk or negedge locked) begin
        if (!locked) begin
            lock_sync <= 0;
            count <= 0;
            reset <= 1;
        end else begin
            lock_sync <= {lock_sync[0],1'b1};
            if (!lock_sync[1]) begin
                count <= 0;
                reset <= 1;
            end else if (reset) begin
                if (count == HOLD_CYCLES-1) reset <= 0;
                else count <= count+1'b1;
            end
        end
    end
endmodule
"}

